//! C for the functions of one module: one `void f_<addr>(Cpu *c)` per guest function, with local flags and
//! registers, jump tables as switches, patch sites, spin gates and loop barriers.

use crate::aot::patches::PatchError;
use crate::loader::Module;
use crate::xlate::flags::{self, FlagError};
use crate::xlate::jumptables::JumpTables;
use crate::xlate::regs;
use crate::xlate::util::hx;
use crate::xlate::{Insn, Kind, Lifter};
use regex::Regex;
use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::sync::LazyLock;

/// Written into every generated file: a commit check can refuse anything carrying it (game-derived code).
/// Kept identical to mkw-recomp's so the output can be compared byte for byte.
pub const GENERATED_MARKER: &str = "MKW_RECOMP_GENERATED_FROM_GAME_CODE";
const MUSTTAIL: &str = "__attribute__((musttail)) return";

pub fn fname(a: u64) -> String {
    format!("f_{a:x}")
}

pub fn header(what: &str) -> String {
    format!("// {GENERATED_MARKER}: {what}, generated by recomp/gen.py from game code. Do not edit or commit.\n")
}

#[derive(Debug, thiserror::Error)]
pub enum EmitError {
    #[error(transparent)]
    Flag(#[from] FlagError),
    #[error(transparent)]
    Patch(#[from] PatchError),
    #[error("{0}")]
    Other(String),
}

type R<T> = Result<T, EmitError>;

#[derive(Debug, Clone, PartialEq, Eq)]
enum Table {
    All,
    Targets(Vec<u64>),
}

static HEX8: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"\b[0-9a-f]{8}\b").unwrap());

/// Emitter options (gen.py's `opts`).
#[derive(Debug, Clone)]
pub struct EmitOptions {
    pub reg_locals: usize,
    pub callee_saved: bool,
}

impl Default for EmitOptions {
    fn default() -> Self {
        EmitOptions { reg_locals: regs::LOCALS, callee_saved: true }
    }
}

pub struct Emitter<'m> {
    pub m: &'m Module,
    starts: HashSet<u64>,
    patched: BTreeMap<u64, (usize, Vec<u32>)>,
    spins: BTreeMap<u64, u64>,
    spanned: BTreeMap<u64, (usize, u64)>,
    reg_locals: usize,
    kept: BTreeSet<u32>,
    sj_owners: BTreeSet<u64>,
    jt: JumpTables<'m>,
    lifter: Lifter,
    pub uses_patches: bool,
    pub stats: BTreeMap<&'static str, u64>,
    pub unsupported: BTreeMap<String, u64>,
}

impl<'m> Emitter<'m> {
    pub fn new(
        m: &'m Module,
        sorted_starts: &[u64],
        patched: BTreeMap<u64, (usize, Vec<u32>)>,
        spins: BTreeMap<u64, u64>,
        spanned: BTreeMap<u64, (usize, u64)>,
        opts: &EmitOptions,
    ) -> Emitter<'m> {
        Emitter {
            m,
            starts: sorted_starts.iter().copied().collect(),
            patched,
            spins,
            spanned,
            reg_locals: opts.reg_locals,
            kept: if opts.callee_saved { regs::callee_saved() } else { BTreeSet::new() },
            sj_owners: crate::aot::discover::setjmp_owners(m, sorted_starts),
            jt: JumpTables::new(m),
            lifter: Lifter::new(),
            uses_patches: false,
            stats: BTreeMap::new(),
            unsupported: BTreeMap::new(),
        }
    }

    fn stat(&mut self, k: &'static str, n: u64) {
        *self.stats.entry(k).or_default() += n;
    }

    fn lift(&self, a: u64) -> Insn {
        self.lifter.lift_or_trap(self.m.word(a), a)
    }

    fn replacements(&self, a: u64) -> Vec<Insn> {
        self.patched[&a].1.iter().map(|&w| self.lifter.lift_or_trap(w, a)).collect()
    }

    fn scan(&mut self, insns: &[Insn], entry: u64, end: u64) -> (BTreeSet<u64>, BTreeMap<u64, Table>) {
        let mut labels = BTreeSet::new();
        let mut tables = BTreeMap::new();
        for (i, ins) in insns.iter().enumerate() {
            match ins.kind {
                Kind::B | Kind::Bcond => {
                    if entry <= ins.target && ins.target < end {
                        labels.insert(ins.target);
                    }
                }
                Kind::Br => {
                    let a = entry + 4 * i as u64;
                    if let Some(jt) = self.jt.resolve(a, entry, end) {
                        self.stat("jump_tables", 1);
                        self.stat("jump_table_targets", jt.len() as u64);
                        labels.extend(jt.iter().copied());
                        tables.insert(a, Table::Targets(jt));
                    } else if self.jt.is_computed(a, entry) {
                        tables.insert(a, Table::All);
                        self.stat("all_label_fallbacks", 1);
                    } else {
                        self.stat("br_dispatch", 1);
                    }
                }
                Kind::Trap => {
                    self.stat("traps", 1);
                    let c = &ins.code;
                    if c.starts_with("rt_udf") && c.contains("/*") {
                        self.stat("unsupported", 1);
                        let msg = c[c.find("/*").unwrap() + 2..c.rfind("*/").unwrap()].trim();
                        let key = HEX8.replace_all(msg, "").trim().to_string();
                        *self.unsupported.entry(key).or_default() += 1;
                    }
                }
                _ => {}
            }
        }
        (labels, tables)
    }

    fn flow(insns: &[Insn], entry: u64, end: u64, tables: &BTreeMap<u64, Table>) -> Vec<Vec<usize>> {
        let idx = |t: u64| -> Vec<usize> {
            if entry <= t && t < end { vec![((t - entry) / 4) as usize] } else { vec![] }
        };
        let mut succ: Vec<Vec<usize>> = insns
            .iter()
            .enumerate()
            .map(|(i, ins)| match ins.kind {
                Kind::Op | Kind::Bl | Kind::Blr => vec![i + 1],
                Kind::B => idx(ins.target),
                Kind::Bcond => {
                    let mut v = idx(ins.target);
                    v.push(i + 1);
                    v
                }
                Kind::Br => match tables.get(&(entry + 4 * i as u64)) {
                    Some(Table::Targets(jt)) => jt.iter().flat_map(|&t| idx(t)).collect(),
                    _ => vec![],
                },
                _ => vec![],
            })
            .collect();
        succ.push(vec![]);
        succ
    }

    fn patched_effect(&self, ins: &Insn, a: u64) -> R<(bool, Option<String>)> {
        let mut alts = vec![];
        let orig = [ins.clone()];
        let repl = self.replacements(a);
        for words in [&orig[..], &repl[..]] {
            let mut fx = vec![];
            for w in words.iter().filter(|w| w.kind == Kind::Op) {
                let e = flags::effect(&w.code)?;
                if e.0 || e.1.is_some() {
                    fx.push(e);
                }
            }
            if fx.len() > 1 {
                return Err(PatchError(format!("{a:#x}: several flag-using words in one alternative")).into());
            }
            alts.push(fx.pop().unwrap_or((false, None)));
        }
        if alts[0].1 != alts[1].1 {
            return Err(PatchError(format!(
                "{a:#x}: the alternatives write different flags ({}, {})",
                py_opt(&alts[0].1),
                py_opt(&alts[1].1)
            ))
            .into());
        }
        if (alts[0].1.is_some() || alts[0].0 || alts[1].0) && ins.kind == Kind::Bl {
            return Err(PatchError(format!("{a:#x}: a patched call that uses flags")).into());
        }
        Ok((alts[0].0 || alts[1].0, alts[0].1.clone()))
    }

    fn flag_plan(
        &self,
        insns: &[Insn],
        entry: u64,
        end: u64,
        succ: &[Vec<usize>],
    ) -> R<flags::Plan> {
        let n = insns.len();
        let mut calls = BTreeSet::new();
        let mut exits: BTreeSet<usize> = [n].into();
        let mut effects = vec![];
        for (i, ins) in insns.iter().enumerate() {
            let a = entry + 4 * i as u64;
            match ins.kind {
                Kind::Bl | Kind::Blr => {
                    calls.insert(i);
                }
                Kind::B | Kind::Bcond if !(entry <= ins.target && ins.target < end) => {
                    exits.insert(i);
                }
                Kind::Br => {
                    exits.insert(i);
                }
                _ => {}
            }
            if self.patched.contains_key(&a) {
                effects.push(self.patched_effect(ins, a)?);
                if self.replacements(a).iter().any(|r| r.kind == Kind::Bl) {
                    calls.insert(i);
                }
            } else {
                effects.push(flags::effect(if ins.kind == Kind::Bcond { &ins.cond } else { &ins.code })?);
            }
        }
        effects.push((false, None));
        Ok(flags::plan(&effects, succ, &calls, &exits))
    }

    /// (lines of C, referenced function starts) for the guest function [entry, end).
    pub fn function(&mut self, entry: u64, end: u64) -> R<(Vec<String>, BTreeSet<u64>)> {
        let insns: Vec<Insn> = (entry..end).step_by(4).map(|a| self.lift(a)).collect();
        let (mut labels, tables) = self.scan(&insns, entry, end);
        let mut refs = BTreeSet::new();
        let sj_owner = self.sj_owners.contains(&entry);
        let all_labels = tables.values().any(|t| *t == Table::All) || sj_owner;
        if sj_owner {
            self.stat("setjmp_owners", 1);
        }
        if all_labels {
            labels = (entry..end).step_by(4).collect();
        }
        let local = !all_labels;
        let (spill, reload, reload_call) =
            if local { (regs::SPILL, regs::RELOAD, regs::RELOAD_CALL) } else { ("", "", "") };
        let succ = if local { Some(Self::flow(&insns, entry, end, &tables)) } else { None };
        let fp = match &succ {
            Some(s) => Some(self.flag_plan(&insns, entry, end, s)?),
            None => None,
        };
        let fp = fp.filter(|p| p.used);
        if let Some(p) = &fp {
            self.stat("local_flag_functions", 1);
            self.stat("flag_reads_direct", p.reader.iter().filter(|k| matches!(k, Some(k) if k != "nz")).count() as u64);
            self.stat("flag_reads_packed", p.reader.iter().filter(|k| matches!(k, Some(k) if k == "nz")).count() as u64);
            self.stat("flag_entry_functions", p.entry as u64);
            self.stat("flag_entry_reads", p.entry_read as u64);
            self.stat("flag_reads_after_call", p.after_call as u64);
            self.stat("flag_publishing_exits", p.exit.iter().filter(|k| k.is_some()).count() as u64);
        }
        let fx = |i: usize, code: &str| -> R<String> {
            match &fp {
                Some(p) => Ok(p.rewrite(i, code)?),
                None => Ok(code.to_string()),
            }
        };
        let publish = |i: usize| -> String { fp.as_ref().map_or(String::new(), |p| p.publish(i)) };

        let mut external_branches = 0u64;
        let mut external_calls = 0u64;
        let starts = &self.starts;
        let mut jump = |t: u64, i: usize, refs: &mut BTreeSet<u64>| -> String {
            if entry <= t && t < end {
                return format!("goto L_{t:x};");
            }
            if starts.contains(&t) {
                refs.insert(t);
                return format!("{}{spill}{MUSTTAIL} {}(c);", publish(i), fname(t));
            }
            external_branches += 1;
            format!("{}{spill}c->pc = {}; {MUSTTAIL} rt_dispatch(c);", publish(i), hx(t))
        };

        let redispatch;
        let mut out: Vec<String>;
        if all_labels {
            let fb = format!("fb_{entry:x}");
            let cases: Vec<String> = (entry..end).step_by(4).map(|t| format!("case {}: goto L_{t:x};", hx(t))).collect();
            redispatch = format!("{MUSTTAIL} {fb}(c);");
            let enter = if sj_owner {
                format!("rt_sj_owner(c, {fb}, {}, {});", hx(entry), hx(end))
            } else {
                redispatch.clone()
            };
            out = vec![
                format!("static void {fb}(Cpu *c);"),
                format!("void {}(Cpu *c) {{", fname(entry)),
                format!("    FN_ENTER({});", hx(entry)),
                format!("    c->pc = {};", hx(entry)),
                format!("    {enter}"),
                "}".into(),
                format!("static void {fb}(Cpu *c) {{"),
                format!("    switch (c->pc) {{ {} default: break; }}", cases.join(" ")),
                format!("    {MUSTTAIL} rt_dispatch(c);"),
            ];
        } else {
            redispatch = format!("{MUSTTAIL} rt_dispatch(c);");
            out = vec![format!("void {}(Cpu *c) {{", fname(entry)), format!("    FN_ENTER({});", hx(entry))];
            if let Some(p) = &fp {
                out.push(format!("    {}", p.decl()));
            }
        }

        let call = |t: u64, a: u64, refs: &mut BTreeSet<u64>, external_calls: &mut u64| -> String {
            if starts.contains(&t) {
                refs.insert(t);
                return format!("c->x[30] = {}; {spill}{}(c);{reload_call}", hx(a + 4), fname(t));
            }
            *external_calls += 1;
            format!("c->x[30] = {}; {spill}c->pc = {}; rt_dispatch(c);{reload_call}", hx(a + 4), hx(t))
        };
        let op = |i: usize, code: &str| -> R<String> {
            let code = fx(i, code)?;
            Ok(if regs::ESCAPE.is_match(&code) { format!("{spill}{code}{reload}") } else { code })
        };

        let mut body: Vec<(Option<usize>, String)> = vec![];

        // Spans the switch skips whole: check that nothing enters them except through their head by fall-through.
        let nins = insns.len();
        let spanned: Vec<(u64, (usize, u64))> = self.spanned.iter().map(|(a, b)| (*a, *b)).collect();
        let mut nspans = 0;
        for &(s, (_sk, se)) in &spanned {
            if se <= entry || s >= end {
                continue;
            }
            if !(entry <= s && se <= end) {
                return Err(PatchError(format!("{s:#x}: span ends at {se:#x}, outside this function")).into());
            }
            let (si, se_i) = (((s - entry) / 4) as usize, ((se - entry) / 4) as usize);
            let mut targets: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
            for (i, ins) in insns.iter().enumerate() {
                let tg: Vec<u64> = match ins.kind {
                    Kind::B | Kind::Bcond => vec![ins.target],
                    Kind::Br => match tables.get(&(entry + 4 * i as u64)) {
                        Some(Table::All) => {
                            return Err(PatchError(format!("{s:#x}: an unresolved computed branch with the span")).into())
                        }
                        Some(Table::Targets(jt)) => jt.iter().copied().filter(|&t| entry <= t && t < end).collect(),
                        None => vec![],
                    },
                    _ => vec![],
                };
                targets.insert(i, tg.into_iter().filter(|&t| entry <= t && t < end).map(|t| ((t - entry) / 4) as usize).collect());
            }
            for (i, _) in insns.iter().enumerate() {
                let a = entry + 4 * i as u64;
                if self.patched.contains_key(&a) && s <= a && a < se {
                    return Err(PatchError(format!("{a:#x}: a site inside the span at {s:#x}")).into());
                }
                for &t in &targets[&i] {
                    let ta = entry + 4 * t as u64;
                    if !(s <= ta && ta < se && !(si <= i && i < se_i)) {
                        continue;
                    }
                    if ta == s {
                        return Err(PatchError(format!("{a:#x}: outside branch to the span head at {s:#x}")).into());
                    }
                    let (mut ok, mut todo, mut back) = (true, vec![i], BTreeSet::new());
                    while let Some(j) = todo.pop() {
                        if !back.insert(j) {
                            continue;
                        }
                        if si <= j && j < se_i {
                            continue;
                        }
                        if j == 0 {
                            ok = false;
                            break;
                        }
                        let mut preds: Vec<usize> = (0..nins).filter(|p| targets[p].contains(&j)).collect();
                        let pj = j - 1;
                        if !matches!(insns[pj].kind, Kind::B | Kind::Br | Kind::Ret | Kind::Trap) {
                            preds.push(pj);
                        }
                        if preds.is_empty() {
                            ok = false;
                            break;
                        }
                        todo.extend(preds);
                    }
                    if !ok {
                        return Err(PatchError(format!("{a:#x}: outside branch into the span at {s:#x}")).into());
                    }
                }
            }
            nspans += 1;
        }

        // Calls up to each instruction: a loop with none needs a compiler barrier on its back edge.
        let mut calls = vec![0usize];
        for ins in &insns {
            calls.push(calls.last().unwrap() + matches!(ins.kind, Kind::Bl | Kind::Blr | Kind::Trap) as usize);
        }

        let mut open_span: Option<u64> = None;
        let mut k = None;
        let (mut spin_gates, mut loop_barriers, mut patched_sites) = (0, 0, 0);
        let mut uses_patches = false;
        for (i, ins) in insns.iter().enumerate() {
            let a = entry + 4 * i as u64;
            if open_span == Some(a) {
                body.push((None, "    }".into()));
                open_span = None;
            }
            if let Some(&(sk, se)) = self.spanned.get(&a) {
                body.push((None, format!("    if (!rt_patch_on[{sk}]) {{")));
                open_span = Some(se);
                uses_patches = true;
            }
            if labels.contains(&a) {
                body.push((None, format!("L_{a:x}:;")));
            }
            k = Some(ins.kind);
            if let Some((set, words)) = self.patched.get(&a) {
                if !matches!(ins.kind, Kind::Op | Kind::Bl) {
                    return Err(PatchError(format!("{a:#x}: patched instruction is a {}", kind_name(ins.kind))).into());
                }
                let mut repl = vec![];
                let rs = self.replacements(a);
                for (j, (w, r)) in words.iter().zip(&rs).enumerate() {
                    if r.kind == Kind::Op {
                        repl.push(op(i, &r.code)?);
                    } else if r.kind == Kind::Bl && j == words.len() - 1 {
                        repl.push(call(r.target, a, &mut refs, &mut external_calls));
                    } else {
                        return Err(PatchError(format!("{a:#x}: replacement word {w:08x} is a {}", kind_name(r.kind))).into());
                    }
                }
                let orig = if ins.kind == Kind::Op {
                    op(i, &ins.code)?
                } else {
                    call(ins.target, a, &mut refs, &mut external_calls)
                };
                uses_patches = true;
                patched_sites += 1;
                body.push((Some(i), format!("    if (rt_patch_on[{set}]) {{ {} }} else {{ {orig} }}", repl.join(" "))));
                continue;
            }
            match ins.kind {
                Kind::Op => body.push((Some(i), format!("    {}", op(i, &ins.code)?))),
                Kind::Trap => body.push((Some(i), format!("    {spill}{}", fx(i, &ins.code)?))),
                Kind::B | Kind::Bcond => {
                    let mut j = jump(ins.target, i, &mut refs);
                    let inside = entry <= ins.target && ins.target < end;
                    if self.spins.get(&a) == Some(&ins.target) && inside {
                        j = format!("rt_spin_gate(c, {}); {j}", hx(ins.target));
                        spin_gates += 1;
                    } else if entry <= ins.target
                        && ins.target <= a
                        && calls[i] == calls[((ins.target - entry) / 4) as usize]
                    {
                        j = format!("__asm__ volatile(\"\" ::: \"memory\"); {j}");
                        loop_barriers += 1;
                    }
                    let line = if ins.kind == Kind::B {
                        format!("    {j}")
                    } else {
                        format!("    if ({}) {{ {j} }}", fx(i, &ins.cond)?)
                    };
                    body.push((Some(i), line));
                }
                Kind::Bl => body.push((Some(i), format!("    {}", call(ins.target, a, &mut refs, &mut external_calls)))),
                Kind::Blr => body.push((
                    Some(i),
                    format!("    c->pc = {}; c->x[30] = {}; {spill}rt_dispatch(c);{reload_call}", ins.target_reg, hx(a + 4)),
                )),
                Kind::Br => match tables.get(&a) {
                    Some(Table::All) => body.push((Some(i), format!("    c->pc = {}; {redispatch}", ins.target_reg))),
                    Some(Table::Targets(jt)) => {
                        let cases: Vec<String> = jt.iter().map(|t| format!("case {}: goto L_{t:x};", hx(*t))).collect();
                        body.push((Some(i), format!("    switch ({}) {{ {} default: break; }}", ins.target_reg, cases.join(" "))));
                        body.push((Some(i), format!("    {}{spill}c->pc = {}; {redispatch}", publish(i), ins.target_reg)));
                    }
                    None => body.push((
                        Some(i),
                        format!("    {}{spill}c->pc = {}; {MUSTTAIL} rt_dispatch(c);", publish(i), ins.target_reg),
                    )),
                },
                Kind::Ret => body.push((Some(i), format!("    {spill}return;"))),
            }
        }
        let n = insns.len();
        if open_span.is_some() {
            body.push((None, "    }".into()));
        }
        if !matches!(k, Some(Kind::B | Kind::Br | Kind::Ret | Kind::Trap)) {
            if end < self.m.hi {
                let j = jump(end, n, &mut refs);
                body.push((Some(n), format!("    {j}")));
            } else {
                body.push((Some(n), format!("    {spill}rt_udf(c, {});", hx(end))));
            }
        }
        if local {
            let mut texts = vec![String::new(); n + 1];
            for (i, line) in &body {
                if let Some(i) = i {
                    texts[*i].push_str(line);
                }
            }
            let clean: BTreeSet<usize> = insns
                .iter()
                .enumerate()
                .filter(|(i, ins)| {
                    !self.patched.contains_key(&(entry + 4 * *i as u64))
                        && (matches!(ins.kind, Kind::Bl | Kind::Blr)
                            || (ins.kind == Kind::Op && texts[*i].contains(regs::RELOAD)))
                })
                .map(|(i, _)| i)
                .collect();
            let rp = regs::plan(&texts, succ.as_ref().unwrap(), &clean, self.reg_locals, &self.kept);
            if !rp.regs.is_empty() {
                out.push(format!("    {}", rp.decl()));
            }
            self.stat("local_reg_functions", !rp.regs.is_empty() as u64);
            self.stat("reg_spills", rp.spill.iter().map(|s| s.len() as u64).sum());
            for (i, line) in &body {
                out.push(match i {
                    None => line.clone(),
                    Some(i) => rp.resolve(*i, line),
                });
            }
        } else {
            out.extend(body.into_iter().map(|(_, l)| l));
        }
        out.push("}".into());
        self.uses_patches |= uses_patches;
        self.stat("external_branches", external_branches);
        self.stat("external_calls", external_calls);
        self.stat("spin_gates", spin_gates);
        self.stat("loop_barriers", loop_barriers);
        self.stat("patched_sites", patched_sites);
        self.stat("spans", nspans);
        self.stat("functions", 1);
        self.stat("instructions", n as u64);
        Ok((out, refs))
    }

    /// C text of one chunk. fns: [(entry, end)].
    pub fn chunk_text(&mut self, name: &str, number: usize, fns: &[(u64, u64)]) -> R<String> {
        self.uses_patches = false;
        let mut body = vec![];
        let mut refs = BTreeSet::new();
        for &(entry, end) in fns {
            let (lines, r) = self.function(entry, end)?;
            body.push(lines.join("\n"));
            refs.extend(r);
        }
        let mut protos: String = refs.iter().map(|r| format!("void {}(Cpu *c);\n", fname(*r))).collect();
        if self.uses_patches {
            protos.push_str("extern uint8_t rt_patch_on[];\n");
        }
        Ok(format!(
            "{}#include \"cpu.h\"\n#include \"simd.h\"\n\n{protos}\n{}\n",
            header(&format!("{name} chunk {number:04}")),
            body.join("\n\n")
        ))
    }
}

fn kind_name(k: Kind) -> &'static str {
    match k {
        Kind::Op => "op",
        Kind::B => "b",
        Kind::Bcond => "bcond",
        Kind::Bl => "bl",
        Kind::Blr => "blr",
        Kind::Br => "br",
        Kind::Ret => "ret",
        Kind::Trap => "trap",
    }
}

fn py_opt(s: &Option<String>) -> String {
    s.clone().unwrap_or_else(|| "None".into())
}

/// `<name>_table.c`: sorted function addresses and pointers for rt_dispatch.
pub fn table_text(name: &str, addrs: &[u64]) -> String {
    let mut s = header(&format!("{name} function table"));
    s.push_str("#include \"cpu.h\"\n\n");
    for a in addrs {
        s.push_str(&format!("void {}(Cpu *c);\n", fname(*a)));
    }
    s.push_str(&format!("\nconst uint64_t {name}_fn_addrs[] = {{\n"));
    s.push_str(&addrs.iter().map(|a| hx(*a)).collect::<Vec<_>>().join(",\n"));
    s.push_str(&format!("\n}};\nconst GuestFn {name}_fn_ptrs[] = {{\n"));
    s.push_str(&addrs.iter().map(|a| fname(*a)).collect::<Vec<_>>().join(",\n"));
    s.push_str(&format!("\n}};\nconst uint64_t {name}_fn_count = {};\n", addrs.len()));
    s
}
